using System.Diagnostics;
using System.Linq.Expressions;
using System.Reflection;
using System.Runtime.ExceptionServices;
using System.Runtime.InteropServices;
using System.Runtime.Versioning;
using System.Security.Cryptography;
using System.Text.Json;

namespace NukeBuild.Tests;

/// <summary>TEST-MCP-SERVICEUPDATE-001: temporary fixtures exercise deployment without a real service.</summary>
[SupportedOSPlatform("linux")]
public sealed class ServiceUpdateTests
{
    /// <summary>Reference doubles establish the required preservation order before production exists.</summary>
    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void MockContract_RestoresBeforeStartAndRetainsBackupOnCopyFailure(bool failCopy)
    {
        var calls = new List<string>();
        Action<string> effect = name => { calls.Add(name); if (failCopy && name == "copy") throw new IOException(); };
        effect("stop");
        effect("archive");
        try { effect("copy"); effect("restore"); effect("start"); effect("health"); }
        catch (IOException) { effect("stop"); effect("restore"); }
        Assert.Equal(failCopy ? ["stop", "archive", "copy", "stop", "restore"] :
            new[] { "stop", "archive", "copy", "restore", "start", "health" }, calls);
    }

    /// <summary>FR-MCP-SERVICEUPDATE-001: host fixtures preserve Windows defaults and select Linux architecture.</summary>
    [Theory]
    [InlineData(true, false, Architecture.X64, "McpServer", "win-x64", "McpServer.Support.Mcp.exe")]
    [InlineData(false, true, Architecture.X64, "mcpserver.service", "linux-x64", "McpServer.Support.Mcp")]
    [InlineData(false, true, Architecture.Arm64, "mcpserver.service", "linux-arm64", "McpServer.Support.Mcp")]
    public void PlatformSelection_PreservesWindowsDefaultsAndSelectsLinuxRid(bool windows, bool linux,
        Architecture architecture, string service, string rid, string executable)
    {
        var value = Call("ServiceUpdatePlatform", "Resolve", null, windows, linux, architecture);
        Assert.Equal(service, Property(value, "DefaultServiceName"));
        Assert.Equal(rid, Property(value, "RuntimeIdentifier"));
        Assert.Equal(executable, Property(value, "ExecutableName"));
        Assert.Equal(windows ? @"C:\ProgramData\McpServer" : "/opt/mcpserver/app", Property(value, "DefaultInstallPath"));
    }

    /// <summary>Unsupported hosts fail before any native effect (TR-MCP-SERVICEUPDATE-001).</summary>
    [Theory]
    [InlineData(false, false, Architecture.X64)]
    [InlineData(false, true, Architecture.X86)]
    public void PlatformSelection_RejectsUnsupportedHosts(bool windows, bool linux, Architecture architecture) =>
        Assert.Throws<PlatformNotSupportedException>(() => Call("ServiceUpdatePlatform", "Resolve", null, windows, linux, architecture));

    /// <summary>Quoted relative YAML and legacy fallback resolve to the actual preserved data root.</summary>
    [Theory]
    [InlineData("DataFolder: '../data'\nMcp:\n  DataDirectory: ignored\n")]
    [InlineData("Mcp:\n  DataDirectory: '../data'\n")]
    public void PreservationPaths_UsesConfiguredDataFolderAndLegacyFallback(string yaml)
    {
        using var f = new Fixture();
        File.WriteAllText(f.Config, yaml);
        var paths = (IEnumerable<string>)Call("WindowsServiceHelper", "GetPreservedStatePaths", null, f.Install);
        Assert.Contains(f.Config, paths);
        Assert.Contains(f.Data, paths);
    }

    /// <summary>Malformed configuration must never silently select the wrong data directory.</summary>
    [Fact]
    public void PreservationPaths_MalformedYamlFailsClosed()
    {
        using var f = new Fixture();
        File.WriteAllText(f.Config, "DataFolder: [unterminated");
        Assert.ThrowsAny<Exception>(() => Call("WindowsServiceHelper", "GetPreservedStatePaths", null, f.Install));
    }

    /// <summary>Legacy install-root data retains database companions and runtime folders only.</summary>
    [Fact]
    public void PreservationPaths_DefaultRootPreservesLegacyFiles()
    {
        using var f = new Fixture();
        File.WriteAllText(f.Config, "DataFolder: .\n");
        File.WriteAllText(Path.Combine(f.Install, "state.db-wal"), "wal");
        Directory.CreateDirectory(Path.Combine(f.Install, "templates"));
        var paths = ((IEnumerable<string>)Call("WindowsServiceHelper", "GetPreservedStatePaths", null, f.Install)).ToArray();
        Assert.Contains(Path.Combine(f.Install, "state.db-wal"), paths);
        Assert.Contains(Path.Combine(f.Install, "templates"), paths);
        Assert.DoesNotContain(f.Executable, paths);
    }

    /// <summary>Missing unit, wrong executable, overlays and link roots cannot reach stop (TR-MCP-SERVICEUPDATE-001).</summary>
    [Theory]
    [InlineData("missing")]
    [InlineData("executable")]
    [InlineData("overlay")]
    [InlineData("environment")]
    [InlineData("symlink")]
    [InlineData("overlap")]
    public void LinuxPreflight_RejectsUnsafeConfigurationWithoutStopping(string defect)
    {
        using var f = new Fixture();
        if (defect == "missing") f.LoadState = "not-found";
        if (defect == "executable") f.UnitExecutable = "/unexpected/server";
        if (defect == "overlay") File.WriteAllText(Path.Combine(f.Install, "appsettings.Production.yaml"), "DataFolder: /wrong");
        if (defect == "environment") File.WriteAllText(f.Env, "DataFolder=/wrong\n");
        if (defect == "symlink") { Directory.Delete(f.Data, true); Directory.CreateSymbolicLink(f.Data, f.Stage); }
        if (defect == "overlap") f.Backup = Path.Combine(f.Data, "backups");
        Assert.ThrowsAny<Exception>(() => f.Update());
        Assert.DoesNotContain("stop", f.Events);
        Assert.Equal("old", File.ReadAllText(f.Executable));
    }

    /// <summary>Real tar with fake systemd validates archive/copy/restore/start ordering and live bytes.</summary>
    [Fact]
    public void LinuxUpdate_ArchivesBeforeReplaceRestoresBeforeStartAndChecksHealth()
    {
        using var f = new Fixture();
        var result = f.Update();
        Assert.True(f.Events.IndexOf("archive") < f.Events.IndexOf("defaults"));
        Assert.True(f.Events.IndexOf("restore") < f.Events.IndexOf("start"));
        Assert.True(f.Events.IndexOf("start") < f.Events.IndexOf("health"));
        Assert.Equal("original", File.ReadAllText(Path.Combine(f.Data, "state")));
        Assert.Equal(f.OriginalConfig, File.ReadAllText(f.Config));
        Assert.True(File.Exists((string)Property(result, "ArchivePath")));
        Assert.Equal(Convert.ToHexString(SHA256.HashData(File.ReadAllBytes((string)Property(result, "ArchivePath")))), Property(result, "ArchiveSha256"));
    }

    /// <summary>Failed archive cannot replace files or start service.</summary>
    [Fact]
    public void LinuxUpdate_BackupFailureNeverCopiesOrStarts()
    {
        using var f = new Fixture { FailArchive = true };
        Assert.ThrowsAny<Exception>(() => f.Update());
        Assert.DoesNotContain("defaults", f.Events);
        Assert.DoesNotContain("start", f.Events);
        Assert.Equal("old", File.ReadAllText(f.Executable));
    }

    /// <summary>Copy and health failures restore live config and retain evidence without claiming binary rollback.</summary>
    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void LinuxUpdate_FailureRestoresAndRetainsArchive(bool failCopy)
    {
        using var f = new Fixture { FailCopy = failCopy, FailHealth = !failCopy };
        Assert.ThrowsAny<Exception>(() => f.Update());
        Assert.Equal(f.OriginalConfig, File.ReadAllText(f.Config));
        Assert.Equal("original", File.ReadAllText(Path.Combine(f.Data, "state")));
        Assert.Equal("restore", f.Events.Last());
        Assert.NotEmpty(Directory.GetFiles(f.Backup, "*.tar", SearchOption.AllDirectories));
    }

    /// <summary>GNU tar preserves modes and symlink targets; private archive protects live secrets.</summary>
    [Fact]
    public void LinuxArchive_UsesPrivateMetadataPreservingCommands()
    {
        using var f = new Fixture();
        File.SetUnixFileMode(f.Env, UnixFileMode.UserRead | UnixFileMode.UserWrite);
        File.CreateSymbolicLink(Path.Combine(f.Data, "link"), "state");
        var result = f.Update();
        var archive = (string)Property(result, "ArchivePath");
        Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite, File.GetUnixFileMode(archive));
        Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute, File.GetUnixFileMode(Path.GetDirectoryName(archive)!));
        Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite, File.GetUnixFileMode(f.Env));
        Assert.Equal("state", new FileInfo(Path.Combine(f.Data, "link")).LinkTarget);
        Assert.Contains("--acls", f.TarArguments);
        Assert.Contains("--xattrs", f.TarArguments);
        Assert.DoesNotContain("--dereference", f.TarArguments);
    }

    /// <summary>A stale directory link is removed without modifying its external target.</summary>
    [Fact]
    public void LinuxReplacement_DoesNotFollowSymlinks()
    {
        using var f = new Fixture();
        Directory.CreateSymbolicLink(Path.Combine(f.Install, "stale"), f.Data);
        f.Update();
        Assert.False(Directory.Exists(Path.Combine(f.Install, "stale")));
        Assert.Equal("original", File.ReadAllText(Path.Combine(f.Data, "state")));
    }

    /// <summary>Concurrent invocation cannot stop or copy while the service lock is held.</summary>
    [Fact]
    public void LinuxUpdate_ConcurrentInvocationFailsWithoutMutation()
    {
        using var f = new Fixture();
        f.OnCopy = () =>
        {
            var before = f.Events.Count;
            Assert.ThrowsAny<Exception>(() => f.Update());
            Assert.DoesNotContain("stop", f.Events.Skip(before));
        };
        f.Update();
    }

    /// <summary>Zero/partial workspace validation is fatal on Linux; Windows helper compatibility remains.</summary>
    [Theory]
    [InlineData(0, 0, 0, false)]
    [InlineData(2, 1, 1, false)]
    [InlineData(2, 1, 0, false)]
    [InlineData(2, 2, 0, true)]
    public void WorkspaceHealth_UnavailableOrEmptyNeverPasses(int count, int healthy, int failed, bool valid)
    {
        Assert.NotNull(Contract("WindowsServiceHelper").GetMethod("RequireHealthyWorkspaces"));
        Action check = () => Call("WindowsServiceHelper", "RequireHealthyWorkspaces", null,
            new WindowsServiceHelper.WorkspaceHealthResult(count, healthy, failed));
        if (valid) check(); else Assert.ThrowsAny<Exception>(check);
    }

    /// <summary>The deployment manifest hashes extensionless Linux apphost rather than only Windows executables.</summary>
    [Fact]
    public void DeploymentManifest_HashesExtensionlessApphost()
    {
        using var f = new Fixture();
        var path = WindowsServiceHelper.WriteDeploymentManifest(f.Install, "example.service", "McpServer.Support.Mcp", 7147, "update");
        using var json = JsonDocument.Parse(File.ReadAllText(path));
        Assert.Contains(json.RootElement.GetProperty("executableHashes").EnumerateArray(), x =>
            x.GetProperty("name").GetString() == "McpServer.Support.Mcp" &&
            x.GetProperty("sha256").GetString()!.Equals(Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(f.Executable))), StringComparison.OrdinalIgnoreCase));
    }

    /// <summary>Reflection keeps absent production contracts compilable for the red gate.</summary>
    private static Type Contract(string name) => typeof(WindowsServiceHelper).Assembly.GetType(name) ?? throw new InvalidOperationException("Missing production contract: " + name);
    /// <summary>Reads a returned contract record.</summary>
    private static object Property(object target, string name) => target.GetType().GetProperty(name)!.GetValue(target)!;
    /// <summary>Invokes the intended API while preserving its original exception for assertions.</summary>
    private static object Call(string type, string method, object? instance, params object[] args)
    {
        try { return (Contract(type).GetMethod(method, BindingFlags.Static | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
            ?? throw new InvalidOperationException("Missing production method: " + method)).Invoke(instance, args)!; }
        catch (TargetInvocationException ex) { ExceptionDispatchInfo.Capture(ex.InnerException!).Throw(); throw; }
    }

    /// <summary>Isolated live-state fixture and command double; tar executes against temporary files only.</summary>
    private sealed class Fixture : IDisposable
    {
        public string Root { get; } = Path.Combine(Path.GetTempPath(), "service-update-" + Guid.NewGuid().ToString("N"));
        public string Install => Path.Combine(Root, "app");
        public string Stage => Path.Combine(Root, "stage");
        public string Data => Path.Combine(Root, "data");
        public string Config => Path.Combine(Install, "appsettings.yaml");
        public string Executable => Path.Combine(Install, "McpServer.Support.Mcp");
        public string Env => Path.Combine(Root, "service.env");
        public string Backup { get; set; }
        public string UnitExecutable { get; set; }
        public string LoadState { get; set; } = "loaded";
        public bool FailArchive { get; set; }
        public bool FailCopy { get; set; }
        public bool FailHealth { get; set; }
        public Action? OnCopy { get; set; }
        public string OriginalConfig => "DataFolder: '" + Data + "'\n";
        public List<string> Events { get; } = [];
        public List<string> TarArguments { get; } = [];
        private bool started;

        /// <summary>Builds ordinary config/data plus an ELF header matching the test RID.</summary>
        public Fixture()
        {
            // Fail the red gate at contract binding, never mistake a missing API for safe rejection.
            _ = Contract("LinuxServiceHelper");
            Assert.NotNull(Contract("WindowsServiceHelper").GetMethod("GetPreservedStatePaths"));
            foreach (var path in new[] { Install, Stage, Data }) Directory.CreateDirectory(path);
            Backup = Path.Combine(Root, "backups"); UnitExecutable = Executable;
            File.WriteAllText(Config, OriginalConfig); File.WriteAllText(Executable, "old");
            File.WriteAllText(Path.Combine(Data, "state"), "original");
            File.WriteAllText(Env, "ConnectionStrings__Default=private\n");
            File.WriteAllText(Path.Combine(Root, "example.service"), "[Service]\n");
            var elf = new byte[64]; elf[0] = 127; elf[1] = 69; elf[2] = 76; elf[3] = 70; elf[4] = 2; elf[5] = 1; elf[18] = 62;
            File.WriteAllBytes(Path.Combine(Stage, "McpServer.Support.Mcp"), elf);
            File.SetUnixFileMode(Path.Combine(Stage, "McpServer.Support.Mcp"), UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute | UnixFileMode.GroupRead | UnixFileMode.GroupExecute | UnixFileMode.OtherRead | UnixFileMode.OtherExecute);
            File.WriteAllText(Path.Combine(Stage, "appsettings.yaml"), "DataFolder: wrong\n");
        }

        /// <summary>Adapts the native-command contract without requiring unimplemented types at compile time.</summary>
        public object Update()
        {
            var resultType = Contract("ServiceCommandResult");
            var command = Expression.Parameter(typeof(string)); var arguments = Expression.Parameter(typeof(IReadOnlyList<string>));
            var body = Expression.Convert(Expression.Call(Expression.Constant(this), GetType().GetMethod(nameof(Run))!, command, arguments), resultType);
            var runner = Expression.Lambda(typeof(Func<,,>).MakeGenericType(typeof(string), typeof(IReadOnlyList<string>), resultType), body, command, arguments).Compile();
            var helper = Activator.CreateInstance(Contract("LinuxServiceHelper"), runner)!;
            var options = Activator.CreateInstance(Contract("LinuxServiceUpdateOptions"), "example.service", Install, Stage, Backup, "linux-x64", Path.Combine(Root, "locks"))!;
            return Call("LinuxServiceHelper", "Update", helper, options, (Action)(() =>
            {
                Events.Add("defaults"); OnCopy?.Invoke();
                if (FailCopy) { File.WriteAllText(Config, "changed"); throw new IOException("injected copy failure"); }
            }), (Action)(() => { Events.Add("health"); if (FailHealth) throw new IOException("injected health failure"); }));
        }

        /// <summary>Fakes systemd/id/readlink; real tar provides independent preservation evidence.</summary>
        public object Run(string command, IReadOnlyList<string> args)
        {
            object Result(int code, string output) => Activator.CreateInstance(Contract("ServiceCommandResult"), code, output)!;
            if (command == "id") return Result(0, "0");
            if (command == "readlink") return Result(0, Executable);
            if (command == "systemctl")
            {
                if (args[0] == "show") return Result(0, $"LoadState={LoadState}\nType=simple\nFragmentPath={Root}/example.service\nDropInPaths=\nEnvironmentFiles={Env} (ignore_errors=no)\nEnvironment=\nWorkingDirectory={Install}\nExecStart={{ path={UnitExecutable} ; argv[]={UnitExecutable} --urls http://localhost:7147 ; ignore_errors=no ; }}\nMainPID={(started ? Environment.ProcessId : 0)}\nActiveState={(started ? "active" : "inactive")}\n");
                if (args[0] == "is-active") return Result(started ? 0 : 3, started ? "active" : "inactive");
                Events.Add(args[0]); if (args[0] == "start") started = true; if (args[0] == "stop") started = false;
                return Result(0, "");
            }
            if (command != "tar") throw new InvalidOperationException("Unexpected command: " + command);
            TarArguments.AddRange(args);
            if (args.Contains("--create")) { Events.Add("archive"); if (FailArchive) return Result(2, "injected"); }
            if (args.Contains("--extract")) Events.Add("restore");
            var info = new ProcessStartInfo(command) { RedirectStandardOutput = true, RedirectStandardError = true };
            foreach (var arg in args) info.ArgumentList.Add(arg);
            using var process = Process.Start(info)!;
            var stdout = process.StandardOutput.ReadToEndAsync(); var stderr = process.StandardError.ReadToEndAsync();
            Assert.True(process.WaitForExit(30000));
            Task.WaitAll(stdout, stderr);
            return Result(process.ExitCode, stdout.Result);
        }

        /// <summary>Removes only this test's temporary tree.</summary>
        public void Dispose() => Directory.Delete(Root, true);
    }
}

# Cross-platform UpdateService

Status: planning gate. Operator explicitly requested implementation and then continued it.
Source baseline: develop / origin/develop `62e612cf1b6dacc392ea406b5e37716ef094212f`.
Requirements: FR-MCP-SERVICEUPDATE-001, TR-MCP-SERVICEUPDATE-001, TEST-MCP-SERVICEUPDATE-001.
TODO: IMPL-SERVICEUPDATE-001.

## Outcome and boundaries

The existing Nuke `UpdateService` target detects Windows or Linux. Windows retains its existing service name, install path, launcher, service-control, backup/restore, and health behavior. Linux updates an existing systemd service, defaulting to `mcpserver.service` and `/opt/mcpserver/app`. Unsupported operating systems/architectures fail before mutations. Linux supports x64 and arm64; the Windows target retains win-x64 compatibility. The existing Windows-only launcher is not published on Linux.

Linux first-time service/account provisioning is outside this update operation. It fails before stopping anything when the named unit is missing, its executable or working directory differs from the selected install directory, or required live configuration is missing. Existing unit, drop-ins, environment files, account, arguments and boot policy are preserved. This keeps local SQL secrets and dedicated service-account configuration intact.

No new package is required. Existing YamlDotNet supports object-based configuration reads. No raw MCP storage edits, force push, history rewrite, or unrelated plugin/cache changes are authorized by this implementation.

## Shared preservation policy

Use the current Windows preservation policy as the shared source: `appsettings.yaml` plus the entire configured root-level `DataFolder` (legacy fallback `Mcp:DataDirectory`); when DataFolder is the install directory, preserve the existing legacy directories and database-file patterns instead of recursively backing up the application itself. Resolve YAML structurally, including quoted/relative paths; malformed configuration fails closed. Windows retains ZIP backups and its existing restore layout.

The initial Linux updater deliberately supports one base `appsettings.yaml`, the service working directory equal to the selected install directory, and no instance/content-root/data-path overrides. Before stopping, reject live `appsettings.json`, environment-specific JSON/YAML overlays, `MCP_INSTANCE`, DataFolder/DataDirectory/instance overrides in inline environment, EnvironmentFile declarations or a running process environment, and `--instance`, data-path or content-root arguments. Inspect values privately and never include environment contents in logs/errors. An inactive existing unit may be updated using its configured environment files and unit properties; a running unit additionally has its process command line/environment checked. These explicit unsupported configurations fail closed rather than silently backing up the wrong data. Database connection environment variables remain supported and unchanged.

Linux collects those same live paths, plus the loaded unit fragment, drop-ins, and EnvironmentFile paths reported by systemd. A private timestamped directory under `/var/backups/mcpserver` holds a GNU tar archive with ownership, modes, ACLs, extended attributes and symbolic links preserved. Directories are mode0700 and the archive mode0600. Required missing environment/configuration paths fail before service stop; optional missing EnvironmentFile entries remain absent. Never print configuration/environment contents. Reject unsafe root paths, symlink preservation roots, backup/source overlap and publish/install overlap before mutation. Nested symlinks are archived without dereferencing.

The service updater preserves file-based data; external SQL databases are not exported or migrated by the backup helper. The server retains its existing startup migration behavior. A retained configuration/data archive is not a database backup or an automatic binary rollback.

## Execution contract

1. Resolve platform defaults and validate explicit parameters. Use shell-free argument lists and bounded subprocess execution. Linux requires effective UID0, systemctl and GNU tar, an installed systemd unit, matching apphost/working directory and a safe archive location. Acquire an exclusive per-service file lock under a private `/run/lock/mcpserver-update` directory before preflight and hold it through failure restoration or successful verification; a concurrent updater fails without service/file mutations. Lock/root/preservation paths and ancestors must not be symlinks.
2. Prepare a unique publish stage before stopping the service (or validate `--skip-build --publish-source`). Validate the Linux apphost is ELF for the selected architecture and is executable. Honor `--skip-version-bump`; for this deployment use it to preserve the approved checkout version. Validate all preserved paths before stop.
3. Stop only the selected unit and verify it stopped. Archive and verify live config/data/systemd state before stale-file removal or copying. Require successful tar creation and listing; record archive SHA256 and verify it before each restore. The real tar smoke additionally verifies original bytes/modes/symlinks and ACLs.
4. Reject stage symlinks and copy only ordinary staged files/directories. Linux cleanup uses ordinal paths and traverses the install tree without following links; unlink stale symlink entries themselves, never recurse through them. Protect preserved roots from cleanup; recheck target paths before copying so an existing symlink cannot redirect writes outside install root. Copy the staged build and brain-slot runtime defaults, then restore preserved live configuration/data from the archive with metadata. Preserve executable mode on the new apphost. Do not rewrite the unit or environment file.
5. Reload systemd, start the selected unit, require active state and matching `/proc/<MainPID>/exe`, then run server and workspace health checks. Existing Windows behavior stays compatible. Linux requires successful health HTTP response, successful `/api-key` authentication bootstrap, successful workspace registry enumeration with at least one enabled workspace, and no enabled workspace failure. Treat unavailable/malformed auth/registry, zero checked/healthy workspaces or nonzero failure count as fatal; an existing helper returning `(0,0,0)` is not success. Write a deployment manifest containing the actual platform apphost hash.
6. Retain the durable archive on success and failure. If copying or validation fails after backup, stop the selected service if necessary and restore preserved configuration/data before throwing. Do not silently claim a binary rollback or success. Keep the publish/backup evidence for recovery on failure; clean only our temporary stage after success.

Use one elevated PowerShell script for any final local deployment and verification. Build/test and publish preparation run as the operator first; the elevated script invokes the validated Nuke target with `--skip-build --skip-version-bump`, then verifies marker rotation, trust, listeners, effective memory and service identity. No manual copy-based deployment substitutes for the target.

## BDPv4 slices and validation

## Implementation interfaces

- `ServiceUpdatePlatform.Resolve(bool windows, bool linux, Architecture architecture)` returns a record with `IsWindows`, `DefaultServiceName`, `DefaultInstallPath`, `ExecutableName`, and `RuntimeIdentifier`; `Current` resolves actual runtime values.
- `WindowsServiceHelper.GetPreservedStatePaths(string installRoot)` exposes the shared preservation-path policy, while its existing Windows backup/restore APIs remain compatible. Its data-path resolver reads root DataFolder and legacy fallback structurally.
- `ServiceCommandResult(int ExitCode, string StandardOutput)` and a `Func<string, IReadOnlyList<string>, ServiceCommandResult>` injected into `LinuxServiceHelper` separate native effects from decisions. The production runner uses ProcessStartInfo.ArgumentList, drains both output streams, has a bounded timeout, and never includes command output/environment in errors.
- `LinuxServiceUpdateOptions(string ServiceName, string InstallPath, string PublishPath, string BackupRoot, string RuntimeIdentifier, string LockRoot)` carries explicit paths/RID; defaults are selected by the Nuke target. `LinuxServiceUpdateResult(string ArchivePath, string ArchiveSha256, int MainPid)` is the non-secret receipt.
- `LinuxServiceHelper.Update(LinuxServiceUpdateOptions options, Action copyRuntimeConfig, Action verifyHealth)` performs the locked lifecycle; injected actions only copy generated defaults inside install root and perform strict health verification. Unit properties/paths are parsed by internal static helpers so deterministic tests exercise actual parsing. Command doubles implement tar create/list/restore over test fixtures; a separate real tar smoke verifies the production archive commands/metadata.
- `WindowsServiceHelper.RequireHealthyWorkspaces(WorkspaceHealthResult result)` is a pure strict result validator used by Linux: Checked>0, Healthy>0, Failed==0. The existing Windows target retains its compatibility behavior.
- `Build.UpdateService` dispatches before calling Windows APIs. Linux publishes main server only, using its resolved RID and a unique stage, then invokes the helper. Existing parameter names remain; add Linux backup-root parameter. Linux lock root is fixed in production and overridable only through the internal options in tests.

All internal/public helpers and test methods receive XML documentation and requirement references. Stage creation/publishing must succeed before stop. No schema or database migration is added.

### Slice 1: requirements and tests

Persist FR/TR/TEST and acceptance criteria through the Codex plugin; map them and create the TODO. Independently review this plan before source implementation.

Add behavior tests first in `tests/Build.Tests/ServiceUpdateTests.cs`. A mock/reference harness covers ordering before exercising production code. Tests named by behavior cover:

- `PlatformSelection_PreservesWindowsDefaultsAndSelectsLinuxRid` and unsupported platforms/architectures.
- `PreservationPaths_UsesConfiguredDataFolderAndLegacyFallback`, including quoted relative paths and malformed YAML.
- `LinuxPreflight_RejectsMissingUnitMismatchedExecutableAndUnsafePaths` without stop/copy commands.
- `LinuxUnitState_ParsesDropInsAndOptionalEnvironmentFiles` with spaces and systemd escaping.
- `LinuxUpdate_ArchivesBeforeReplaceRestoresBeforeStartAndChecksHealth` with command doubles and temporary directories.
- `LinuxUpdate_BackupFailureNeverCopiesOrStarts`, `LinuxUpdate_CopyFailureRestoresAndRetainsArchive`, and `LinuxUpdate_HealthFailureStopsAndRetainsEvidence`.
- `LinuxArchive_UsesPrivateMetadataPreservingCommands` and `DeploymentManifest_HashesExtensionlessApphost`.
- `LinuxUpdate_ConcurrentInvocationFailsWithoutMutation`, `LinuxPreflight_RejectsUnsupportedConfigurationOverrides`, `LinuxReplacement_DoesNotFollowSymlinks`, and `WorkspaceHealth_UnavailableOrEmptyNeverPasses`.

Expected red: production contract absent or unsupported Linux behavior. Mocks-first behavior tests must pass before adding the production implementation. Independent red gate records actual expected failures; no skipped placeholders.

### Slice 2: implementation and regression

Add platform resolution and Linux lifecycle helpers with injected command execution for deterministic tests; dispatch from the existing target. Reuse the preservation policy and health checks; retain Windows defaults and launcher behavior. XML-document all new APIs/tests. Validate each changed source project compiles through the Codex code-verification hook.

